1	"use client";
2	
3	import Script from "next/script";
4	import type { PublicTrackingConfig } from "@/lib/tracking";
5	
6	/**
7	 * Browser-side ad tags: Meta Pixel + Google Ads/GA4 gtag. Handed the PUBLIC config
8	 * (no CAPI token) read from Settings, and renders nothing unless an ID is set. Also
9	 * installs `window.nxTrack(event, params)` so any client component can fire a
10	 * conversion (e.g. a Purchase on the order-success view) to BOTH Meta and Google in
11	 * one call, using a shared event_id for dedup with CAPI.
12	 *
13	 * Consent gating lives in its wrapper `ConsentedTags.tsx` — these scripts are only
14	 * ever mounted once the visitor has accepted all cookies, so the marketing/advertising
15	 * pixels never load without consent.
16	 */
17	export function ConversionTags({ config }: { config: PublicTrackingConfig }) {
18	  const { metaPixelId, ga4Id, googleAdsId, googleAdsPurchaseLabel } = config;
19	  if (!metaPixelId && !ga4Id && !googleAdsId) return null;
20	
21	  const gtagId = ga4Id || googleAdsId; // one gtag.js load covers both
22	  return (
23	    <>
24	      {metaPixelId && (
25	        <Script id="meta-pixel" strategy="afterInteractive">
26	          {`!function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?
27	n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;
28	n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;
29	t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,
30	document,'script','https://connect.facebook.net/en_US/fbevents.js');
31	fbq('init','${metaPixelId}');fbq('track','PageView');`}
32	        </Script>
33	      )}
34	      {gtagId && (
35	        <>
36	          <Script src={`https://www.googletagmanager.com/gtag/js?id=${gtagId}`} strategy="afterInteractive" />
37	          <Script id="gtag-init" strategy="afterInteractive">
38	            {`window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}
39	gtag('js',new Date());${ga4Id ? `gtag('config','${ga4Id}');` : ""}${googleAdsId ? `gtag('config','${googleAdsId}');` : ""}`}
40	          </Script>
41	        </>
42	      )}
43	      {/* Unified conversion helper. Usage: window.nxTrack('Purchase',{value:3.29,currency:'USD',eventId}) */}
44	      <Script id="nx-track" strategy="afterInteractive">
45	        {`window.nxTrack=function(evt,p){p=p||{};try{
46	if(window.fbq){fbq('track',evt,{value:p.value,currency:p.currency||'USD'},p.eventId?{eventID:p.eventId}:undefined);}
47	if(window.gtag){
48	  if('${ga4Id}')gtag('event',evt.toLowerCase(),{value:p.value,currency:p.currency||'USD'});
49	  ${googleAdsId && googleAdsPurchaseLabel ? `if(evt==='Purchase')gtag('event','conversion',{send_to:'${googleAdsId}/${googleAdsPurchaseLabel}',value:p.value,currency:p.currency||'USD',transaction_id:p.eventId||''});` : ""}
50	}
51	}catch(e){}};`}
52	      </Script>
53	    </>
54	  );
55	}
