1	// Ads conversion tracking — Meta Pixel + Google Ads/GA4, browser + server-side.
2	//
3	// IDs live in Settings (admin-editable, no redeploy). The browser side is injected
4	// by components/marketing/ConversionTags.tsx; the SERVER side is the Meta
5	// Conversions API (CAPI) below, which recovers the conversions iOS/ad-blockers hide
6	// from the pixel. Everything is inert until the IDs/token are set — no config,
7	// nothing fires, nothing leaks.
8	import { createHash, randomUUID } from "node:crypto";
9	import { getSetting } from "@/lib/settings";
10	import { decryptSecret } from "@/lib/crypto-box";
11	
12	export type TrackingConfig = {
13	  metaPixelId: string;
14	  ga4Id: string;
15	  googleAdsId: string; // AW-XXXXXXXXX
16	  googleAdsPurchaseLabel: string; // conversion label for a purchase
17	  // Server-only (never sent to the browser):
18	  metaCapiToken: string;
19	  metaTestEventCode: string;
20	};
21	
22	/** Public (browser-safe) subset — safe to serialize into the page. */
23	export type PublicTrackingConfig = Pick<
24	  TrackingConfig,
25	  "metaPixelId" | "ga4Id" | "googleAdsId" | "googleAdsPurchaseLabel"
26	>;
27	
28	export async function loadTrackingConfig(): Promise<TrackingConfig> {
29	  const [metaPixelId, ga4Id, googleAdsId, googleAdsPurchaseLabel, metaCapiToken, metaTestEventCode] =
30	    await Promise.all([
31	      getSetting("meta_pixel_id", ""),
32	      getSetting("ga4_measurement_id", ""),
33	      getSetting("google_ads_id", ""),
34	      getSetting("google_ads_purchase_label", ""),
35	      getSetting("meta_capi_token", ""),
36	      getSetting("meta_test_event_code", ""),
37	    ]);
38	  // The CAPI token is stored encrypted (a `secret` field); decrypt for use.
39	  const decToken = metaCapiToken ? (decryptSecret(metaCapiToken) ?? metaCapiToken) : "";
40	  return {
41	    metaPixelId: metaPixelId.trim(),
42	    ga4Id: ga4Id.trim(),
43	    googleAdsId: googleAdsId.trim(),
44	    googleAdsPurchaseLabel: googleAdsPurchaseLabel.trim(),
45	    metaCapiToken: decToken.trim(),
46	    metaTestEventCode: metaTestEventCode.trim(),
47	  };
48	}
49	
50	export function toPublicConfig(c: TrackingConfig): PublicTrackingConfig {
51	  return {
52	    metaPixelId: c.metaPixelId,
53	    ga4Id: c.ga4Id,
54	    googleAdsId: c.googleAdsId,
55	    googleAdsPurchaseLabel: c.googleAdsPurchaseLabel,
56	  };
57	}
58	
59	function sha256Lower(s: string): string {
60	  return createHash("sha256").update(s.trim().toLowerCase()).digest("hex");
61	}
62	
63	export type CapiEvent = {
64	  eventName: "Purchase" | "Lead" | "CompleteRegistration" | "Subscribe";
65	  /** Stable id so the browser pixel + this server event dedupe to ONE conversion. */
66	  eventId?: string;
67	  email?: string;
68	  value?: number;
69	  currency?: string;
70	  /** The page the conversion happened on (for event_source_url). */
71	  sourceUrl?: string;
72	  clientIp?: string;
73	  userAgent?: string;
74	  /** Meta click-id cookie (_fbc) — sent RAW (not hashed) per Meta spec. */
75	  fbc?: string;
76	  /** Meta browser-id cookie (_fbp) — sent RAW (not hashed) per Meta spec. */
77	  fbp?: string;
78	  /** A stable id for the person (we use the user id, hashed) — big match boost. */
79	  externalId?: string;
80	};
81	
82	/**
83	 * Fire a server-side Meta Conversions API event. Best-effort: never throws into
84	 * the caller (a tracking failure must never break an order). Returns the event_id
85	 * used so the caller can pass the SAME id to the browser pixel for dedup.
86	 */
87	export async function sendMetaConversion(ev: CapiEvent): Promise<{ ok: boolean; eventId: string }> {
88	  const eventId = ev.eventId ?? randomUUID();
89	  try {
90	    const cfg = await loadTrackingConfig();
91	    if (!cfg.metaPixelId || !cfg.metaCapiToken) return { ok: false, eventId };
92	
93	    const userData: Record<string, unknown> = {};
94	    if (ev.email) userData.em = [sha256Lower(ev.email)];
95	    if (ev.clientIp) userData.client_ip_address = ev.clientIp;
96	    if (ev.userAgent) userData.client_user_agent = ev.userAgent;
97	    // fbc/fbp are sent RAW (Meta hashes nothing here); external_id IS hashed. All
98	    // three materially lift the event match rate when present.
99	    if (ev.fbc) userData.fbc = ev.fbc;
100	    if (ev.fbp) userData.fbp = ev.fbp;
101	    if (ev.externalId) userData.external_id = [sha256Lower(ev.externalId)];
102	
103	    const body: Record<string, unknown> = {
104	      data: [
105	        {
106	          event_name: ev.eventName,
107	          event_time: Math.floor(Date.now() / 1000),
108	          action_source: "website",
109	          event_id: eventId,
110	          ...(ev.sourceUrl ? { event_source_url: ev.sourceUrl } : {}),
111	          user_data: userData,
112	          ...(ev.value != null
113	            ? { custom_data: { value: Number(ev.value.toFixed(2)), currency: ev.currency ?? "USD" } }
114	            : {}),
115	        },
116	      ],
117	      ...(cfg.metaTestEventCode ? { test_event_code: cfg.metaTestEventCode } : {}),
118	    };
119	
120	    const url = `https://graph.facebook.com/v21.0/${encodeURIComponent(cfg.metaPixelId)}/events?access_token=${encodeURIComponent(cfg.metaCapiToken)}`;
121	    const res = await fetch(url, {
122	      method: "POST",
123	      headers: { "Content-Type": "application/json" },
124	      body: JSON.stringify(body),
125	      // Don't let a slow Meta endpoint hang a checkout.
126	      signal: AbortSignal.timeout(4000),
127	    });
128	    return { ok: res.ok, eventId };
129	  } catch {
130	    return { ok: false, eventId };
131	  }
132	}
