28	/**
29	 * Send the customer to Stripe's hosted setup page.
30	 *
31	 * `startCardSetup` returns a URL, so this is a full navigation rather than a
32	 * fetch — the same shape as `AddFunds`, and the reason no card data ever reaches
33	 * this origin.
34	 */
35	export function AddCardButton({
36	  label = "Add a card",
37	  className = "btn-primary",
38	}: {
39	  label?: string;
40	  className?: string;
41	}) {
42	  const [error, setError] = useState<string | null>(null);
43	  const [pending, start] = useTransition();
44	
45	  const go = () => {
46	    setError(null);
47	    start(async () => {
48	      const res = await startCardSetup();
49	      if (res.url) {
50	        window.location.href = res.url;
51	        return;
52	      }
53	      setError(res.error ?? "We couldn't start card setup. Please try again in a moment.");
54	    });
55	  };
56	
57	  return (
58	    <div>
59	      <button className={className} onClick={go} disabled={pending}>
60	        {pending ? "Redirecting…" : label}
61	      </button>
62	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
63	    </div>
64	  );
65	}
