381	  const [retryPending, startRetry] = useTransition();
382	  const [error, setError] = useState<string | null>(null);
383	  // A success-with-a-caveat, distinct from an error: e.g. removed from the account
384	  // while the mail server was unreachable, so the mailbox itself may still exist.
385	  // Red would read as failure; nothing would hide a fact the customer needs.
386	  const [notice, setNotice] = useState<string | null>(null);
387	  const [password, setPassword] = useState<string | null>(null);
388	  const [pwNote, setPwNote] = useState<string | null>(null);
389	  const [status, setStatus] = useState(mailbox.status);
390	
391	  const badge = statusBadge(status);
392	  // Only a live mailbox can actually be signed in to. Offering "Open inbox" on a
393	  // FAILED row would send the customer to a webmail error page instead of
394	  // telling them the mailbox was never created on the mail server.
