427	    if (!confirm(`Reset the password for ${mailbox.address}? The current password will stop working.`)) return;
428	    setError(null);
429	    setPwNote(null);
430	    startPw(async () => {
431	      const res = await resetMailboxPassword(mailbox.id);
432	      if (res?.error) setError(res.error);
433	      else if (res?.password) {
434	        setPassword(res.password);
435	        setPwNote("New password set — copy it now, it won't be shown again automatically.");
436	      }
437	    });
438	  }
439	
440	  return (
441	    <div className="rounded-lg border border-white/[0.06] px-3 py-2">
442	      <div className="flex flex-wrap items-center justify-between gap-2">
443	        <div className="flex flex-wrap items-center gap-2">
444	          <span className="font-mono text-sm text-white">{mailbox.address}</span>
445	          <Badge tone={badge.tone}>{badge.label}</Badge>
446	        </div>
447	        <div className="flex flex-wrap items-center gap-2">
448	          {/* Per-mailbox action. The panel previously offered one generic
449	              "Open inbox →" for the whole account, which always landed on the
450	              oldest mailbox — so a customer with several boxes had no way to
451	              open the one they were looking at. `?mailbox=` is validated
452	              server-side against the mailboxes this user owns. */}
