591	  const [pending, start] = useTransition();
592	
593	  function run() {
594	    setError(null);
595	    start(async () => {
596	      const res = await checkEmailDeliverability(subscriptionId);
597	      if (res?.error) {
598	        setError(res.error);
599	        setReport(null);
600	      } else if (res?.report) {
601	        setReport(res.report);
602	      }
603	    });
604	  }
605	
606	  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
607	  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
608	  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;
609	
610	  return (
611	    <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
612	      <div className="flex flex-wrap items-center justify-between gap-2">
613	        <div className="flex flex-wrap items-center gap-2">
