627	              <Badge tone="green">All checks pass</Badge>
628	            ))}
629	        </div>
630	        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
631	          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
632	        </button>
633	      </div>
634	
635	      <p className="mt-2 text-xs text-slate-400">
636	        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
