638	      </p>
639	
640	      {error && (
641	        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
642	          {error}
643	        </div>
644	      )}
645	
646	      {report && (
647	        <div className="mt-3 space-y-2">
648	          {report.error && (
649	            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
650	              {report.error}
651	            </div>
652	          )}
653	
654	          {report.checks.map((c) => (
655	            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
656	              <div className="flex flex-wrap items-center gap-2">
657	                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
658	                <span className="text-sm font-medium text-slate-200">{c.label}</span>
659	                <span className="text-[11px] text-slate-500">
660	                  {c.type} · <span className="font-mono">{c.host}</span>
661	                </span>
662	              </div>
663	
664	              <div className="mt-2 grid gap-2 sm:grid-cols-2">
665	                <div className="min-w-0">
666	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
667	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
668	                    {c.observed || "— nothing published —"}
669	                  </code>
670	                </div>
671	                <div className="min-w-0">
672	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
673	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
674	                    {c.expected || "—"}
675	                  </code>
676	                </div>
677	              </div>
678	
679	              <p
680	                className={`mt-2 text-xs ${
681	                  c.status === "fail"
682	                    ? "text-red-400"
683	                    : c.status === "warn"
684	                      ? "text-amber-400"
685	                      : c.status === "pass"
686	                        ? "text-emerald-300/80"
687	                        : "text-slate-400"
688	                }`}
689	              >
690	                {c.detail}
691	              </p>
692	            </div>
693	          ))}
694	
695	          {/* Printing the nameservers is the point, not decoration: it is how the
696	              customer (or support) can tell this answer came from the zone's own
697	              authority and not from a stale recursive cache. */}
698	          <p className="text-[11px] text-slate-500">
699	            {report.nameservers.length > 0 ? (
700	              <>
701	                Read directly from this domain&apos;s nameservers (
702	                <span className="font-mono">{report.nameservers.join(", ")}</span>), so a record you
703	                just changed shows up straight away.
704	              </>
705	            ) : (
706	              <>Couldn&apos;t reach this domain&apos;s nameservers, so no record could be read.</>
707	            )}{" "}
708	            Checked {new Date(report.checkedAt).toLocaleTimeString()}.
709	          </p>
710	        </div>
711	      )}
712	    </div>
713	  );
714	}
